import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header with correct columns', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv includes one invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[2], '');
});

test('exportCsv exports invoice number', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].startsWith('INV-2026-0001,'), true);
});

test('exportCsv exports customer name not id', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[1], 'Alice');
});

test('exportCsv exports dates', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[2], '2026-10-07');
  assert.equal(fields[3], '2026-10-21');
});

test('exportCsv exports status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[4], 'issued');
});

test('exportCsv exports amounts as euros with 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '950.00');
});

test('exportCsv exports discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[6], (totals.discount / 100).toFixed(2));
});

test('exportCsv exports VAT', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[7], (totals.vat / 100).toFixed(2));
});

test('exportCsv exports total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[8], (totals.total / 100).toFixed(2));
});

test('exportCsv exports due amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[9], (totals.total / 100).toFixed(2));
});

test('exportCsv exports multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 50 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert.equal(lines[1].startsWith('INV-2026-0001,'), true);
  assert.equal(lines[2].startsWith('INV-2026-0002,'), true);
});

test('exportCsv maintains invoice order', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 50 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result1 = exportCsv([issued1, issued2]);
  const result2 = exportCsv([issued2, issued1]);

  const lines1 = result1.split('\n');
  const lines2 = result2.split('\n');

  assert.equal(lines1[1].startsWith('INV-2026-0001,'), true);
  assert.equal(lines1[2].startsWith('INV-2026-0002,'), true);

  assert.equal(lines2[1].startsWith('INV-2026-0002,'), true);
  assert.equal(lines2[2].startsWith('INV-2026-0001,'), true);
});

test('exportCsv escapes commas in customer name', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('"'), true);
});

test('exportCsv handles empty invoices array', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], '');
});

test('exportCsv shows due amount after partial payment', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partial = recordPayment(issued, { amount: totals.total / 2, date: '2026-10-20' }).value;

  const result = exportCsv([partial]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const due = totals.total / 2;
  assert.equal(fields[9], (due / 100).toFixed(2));
});

test('exportCsv uses dot as decimal separator', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('.'), true);
  assert.equal(lines[1].includes(','), true);
});

test('exportCsv does not add currency sign', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('€'), false);
  assert.equal(lines[1].includes('EUR'), false);
});

test('exportCsv does not use thousands separator', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(/\d+\.\d+/.test(lines[1]), true);
  assert.equal(lines[1].includes(' '), false);
});

test('exportCsv escapes double quotes', () => {
  const inv = {
    number: 'INV-2026-0001',
    customerName: 'Alice "The Great" Smith',
    issueDate: '2026-10-07',
    dueDate: '2026-10-21',
    status: 'issued',
    lines: [{ sku: 'DEV-HOUR', qty: 100, unitPrice: 9500, vatRate: 21, discountPercent: 0, name: 'Dev' }],
    payments: [],
  };

  const result = exportCsv([inv]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('""'), true);
});

test('exportCsv shows draft status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;

  const result = exportCsv([inv]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[4], 'draft');
});

test('exportCsv each line ends with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[0].endsWith('\n'), false);
  assert.equal(result.includes('\n'), true);
});

